\begin{array}{c|ccccc} \multicolumn{2}{r}{x^3} & +6x^2 & +3x & +7 \\ \cline{2-6} x-1 & x^4 & +5x^3 & +9x^2 & -x & -14 \\ \multicolumn{2}{r}{x^4} & -x^3 \\ \cline{2-3} \multicolumn{2}{r}{0} & 6x^3 & +9x^2 \\ \multicolumn{2}{r}{} & 6x^3 & -6x^2 \\ \cline{3-4} \multicolumn{2}{r}{} & 0 & 15x^2 & -x \\ \multicolumn{2}{r}{} & & 15x^2 & -15x \\ \cline{4-5} \multicolumn{2}{r}{} & & 0 & 14x & -14 \\ \multicolumn{2}{r}{} & & & 14x & -14 \\ \cline{5-6} \multicolumn{2}{r}{} & & & 0 & 0 \\ \end{array}
